/** Resolve nome por código RFB (4 dígitos CNPJ) ou IBGE (7 dígitos). */
export function resolveMunicipioNome(
  codigo: string | number | undefined | null,
  _ufFallback?: string | undefined | null,
): string {
  const digits = String(codigo ?? '').replace(/\D/g, '');
  if (!digits) return 'Desconhecido';
  if (digits.length <= 4) {
    const hit = CODIGO_RFB_PARA_MUNICIPIO[digits.padStart(4, '0')];
    if (hit) return hit.nome;
  }
  if (digits.length >= 7) {
    const hit = CODIGO_IBGE_PARA_MUNICIPIO[digits.padStart(7, '0')];
    if (hit) return hit.nome;
  }
  const rfb = CODIGO_RFB_PARA_MUNICIPIO[digits.padStart(4, '0')];
  if (rfb) return rfb.nome;
  const ibge = CODIGO_IBGE_PARA_MUNICIPIO[digits.padStart(7, '0')];
  if (ibge) return ibge.nome;
  return `Município (Cód. ${digits})`;
}

export function resolveMunicipioRef(
  codigo: string | number | undefined | null,
): MunicipioRef | null {
  const digits = String(codigo ?? '').replace(/\D/g, '');
  if (!digits) return null;
  if (digits.length <= 4) {
    return CODIGO_RFB_PARA_MUNICIPIO[digits.padStart(4, '0')] ?? null;
  }
  if (digits.length >= 7) {
    return CODIGO_IBGE_PARA_MUNICIPIO[digits.padStart(7, '0')] ?? null;
  }
  return (
    CODIGO_RFB_PARA_MUNICIPIO[digits.padStart(4, '0')] ??
    CODIGO_IBGE_PARA_MUNICIPIO[digits.padStart(7, '0')] ??
    null
  );
}
